        // 90점 이상은 우수, 60점 이상은 합격이에요.
        int score = 95;
        // 위에서부터 차례로 검사해요.
        if (score >= 60) {  // 60점 이상이면 합격이에요.
            System.out.println(score + "점: 합격");
        } else if (score >= 90) {  // 90점 이상이면 우수예요.
